esbmc_test_source:
contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // attemptAmount is the amount parameter to withdraw/withdrawAll (unused for withdrawAll but kept as input)
    function run(uint attemptAmount) public payable {
        // This test assumes the caller (this contract) is NOT the owner of c. Since the checker deploys a fresh C
        // with owner = deployer (the harness), and then gives that C to this test's constructor, this contract
        // is not the original owner. No require on c's state.

        // Observe before state via public getters / balances
        address beforeOwner = c.owner(); if (__ESBMC_reverted()) return;
        uint beforeDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint beforeBal = address(c).balance;

        // Try calling withdrawAll as non-owner and catch whether it reverts
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Observe after state
        address afterOwner = c.owner(); if (__ESBMC_reverted()) return;
        uint afterDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint afterBal = address(c).balance;

        // General rule: for this non-owner caller, withdrawAll must either revert leaving depositsCount and balance unchanged,
        // or (if it unexpectedly succeeds) it must preserve owner and reduce C's balance by at most the prior balance (i.e., not increase it),
        // and depositsCount must not increase. To be a useful invariant that should hold for correct C, we assert that owner never changes,
        // depositsCount does not increase, and if the call reverted then both balance and depositsCount stayed exactly the same.
        assert(
            afterOwner == beforeOwner
            && afterDeposits >= beforeDeposits
            && (reverted ? (afterDeposits == beforeDeposits && afterBal == beforeBal) : (afterDeposits == beforeDeposits && afterBal <= beforeBal))
        );
    }

    receive() external payable {}
}

