// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 attemptAmount) internal {
        address beforeOwner;
        try c.owner() returns (address __r) { beforeOwner = __r; } catch { return; }
        uint256 beforeDeposits;
        try c.depositsCount() returns (uint256 __r) { beforeDeposits = __r; } catch { return; }
        uint beforeBal = address(c).balance;
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }
        address afterOwner;
        try c.owner() returns (address __r) { afterOwner = __r; } catch { return; }
        uint256 afterDeposits;
        try c.depositsCount() returns (uint256 __r) { afterDeposits = __r; } catch { return; }
        uint afterBal = address(c).balance;
        assertTrue(afterOwner == beforeOwner
            && afterDeposits >= beforeDeposits
            && (reverted ? (afterDeposits == beforeDeposits && afterBal == beforeBal) : (afterDeposits == beforeDeposits && afterBal <= beforeBal)));
    }

    function testFuzz_run(uint256 attemptAmount) public {
        _run(attemptAmount);
    }

    receive() external payable {}
}
